insert into public.word_senses (id, stable_key, word_id, module_id, category_id, meaning_en, meaning_zh, usage_note)
values
  ('cb8e5a9f-f438-526d-a828-364107d05149', 'research_english:general_research:implicate:verb', '99ecdc14-d4d5-5bb3-b2ea-39b6f9a4a1a7', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to suggest that a factor is involved in a process or outcome', '提示……可能参与；牵涉', '证据只够指向某个因素可能介入，还没证明它就是原因。比 demonstrate 弱，不要写成已经证实。'),
  ('3b5e0527-6d56-5388-b8cc-a97cdf46a9a5', 'research_english:general_research:preclude:verb', '87187316-0ac9-52db-a9ee-61b72b32beda', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to make a stronger claim or analysis impossible because of a limitation', '使……无法成立；排除作出更强结论的可能', '局限已经大到某类推断做不成时才用。普通缺点用 limit；还没堵死更强结论就别写 preclude。'),
  ('28eb0fd6-ba27-5346-b7b4-03ff4523598f', 'research_english:general_research:mediate:verb', '418fdef6-8e2c-5936-b0d4-37e2819b28af', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to act as an intermediate pathway through which an effect is transmitted', '介导；作为中间环节传递效应', '中间变量被检验后，效应有一部分经它传递才能写 mediate。只是相关或同时出现不够。'),
  ('ce18c099-ce07-5688-8b46-eb192373aac4', 'research_english:general_research:mitigate:verb', 'c3b47953-71cd-5581-b9c9-2ac55a23b4e9', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to reduce the severity of a risk, bias, or unwanted effect without removing it', '减轻；缓解（风险或偏倚）', '风险或偏倚被压小但还在。eliminate 是去掉；只说注意到了问题也不够。'),
  ('90ac5257-05bd-5870-8fb8-3807189f5502', 'research_english:general_research:substantiate:verb', '1aaf167f-4faf-5f42-89ca-d69910694134', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to provide enough evidence to make a claim credible', '证实；为主张提供足够证据', '证据已经把主张撑住，比 suggest 强，比 prove 仍留余地。只有提示或重复同一分析不要写。'),
  ('3620b02c-dda4-55bd-bd39-9480a6d4afd5', 'research_english:general_research:putative:adjective', 'd455cae0-96cb-59e2-a1d7-32fc30f9b0f5', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'widely supposed or proposed but not yet demonstrated', '推定的；假定的；尚未证实的', '还只是公认猜测或工作假说。已经实验证实就改用 demonstrated，不要再写 putative。'),
  ('a67220c9-38c7-591d-a9d1-5408625800a1', 'research_english:general_research:modest:adjective', '6d386afe-0374-5698-bbf4-522e68d99293', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'noticeable but small in size or practical importance', '不大的；幅度有限的', '效应真实存在但幅度小。modest 不等于 statistically significant，也别夸成 substantial。'),
  ('bd4e1861-270c-50fe-942c-a81d70afaa0c', 'research_english:general_research:constrain:verb', '31d522dc-cfae-5183-8b7a-b3e95de6bd04', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to limit what can be inferred or done because of a boundary or shortage', '限制；约束（可推断或可做的范围）', '边界还在，只是活动空间变窄。preclude 是直接做不成；普通提到局限不必上 constrain。'),
  ('c96931aa-afbe-542b-b631-0a3e4c4351b7', 'research_english:general_research:confound:verb', '2c0e2de1-eaa5-5b69-87a2-be6063b6de29', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to distort an apparent association by mixing in the effect of another factor', '造成混杂；把关联拧偏', '动词指某个因素把暴露–结局关联拧弯。名词 confounding 才是那种偏倚本身，不要混用词性。'),
  ('dfa100f3-7fb1-51a0-bd1f-3daf196598f0', 'research_english:general_research:plausible:adjective', '68ea5eac-993c-532e-b05d-65ddadfedd76', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'believable given current knowledge, without being shown to be true', '说得通的；看似合理的', '机制或解释在现有知识下站得住，但还没被证明。proven 或 demonstrated 更强，不要提前用。'),
  ('2dcadd58-022e-5d3c-8cf0-a256acb1fc78', 'research_english:general_research:tentative:adjective', '06869622-8b42-5540-b897-7522deee65d6', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'offered as a cautious, still-reversible conclusion', '初步的；暂定的；需谨慎对待的', '结论还经不起大力气推广。definitive 完全相反；有独立重复后就不要再写 tentative。'),
  ('591d8b92-57dd-5448-b9cd-1ad39f7afb8a', 'research_english:general_research:attributable:adjective', '125c61ed-e13b-5ed3-a539-4f8249867e49', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'reasonably assigned to a stated cause after other explanations are considered', '可归因于；可归咎于', '在考虑了其他解释后，仍能把效应派给某个因素。相关或伴随出现不够，也不等于已经证明因果。'),
  ('6bdfe2cf-1a8c-5cd3-bb19-2ce5c1f78768', 'research_english:general_research:caveat:noun', '8c12c0dc-70da-57e2-905d-6e3c6e575976', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'an explicit warning that limits how far a result should be trusted or applied', '需注意的限制；解读上的保留条件', '用来卡住过度推广。普通 limitation 是弱点清单；caveat 更强调“用这个结果时先记住这一点”。'),
  ('c527cce5-d3a7-5bf2-a9cc-305b917c8a81', 'research_english:general_research:abrogate:verb', '433d4cab-8a45-54aa-b5da-26b3fffedb0c', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to abolish a biological effect so that it is no longer observed', '废除；使效应消失', '干预后效应基本没了，比 attenuate 或 reduce 更决断。只是减弱就别写成 abrogate。'),
  ('b69dd7a9-5a30-5c7f-bfb4-97f2c539513b', 'research_english:general_research:underscore:verb', '1995a162-dd8d-5570-85bf-464eed69ed04', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to emphasize that a finding makes a point especially clear', '强调；凸显', '结果把某一点衬得很醒目时才用。不要用来宣布新发现，也不要和 statistically significant 混为一谈。'),
  ('53e70487-eca8-52ff-857a-7fca22c30b70', 'research_english:statistics_methodology:censor:verb', '4a73ae9b-6400-52d2-9264-13533d22dbd9', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2ea63ebe-26b8-5460-b60d-663b588b828e', 'to treat a survival observation as incomplete at the last time the outcome was known not to have occurred', '删失；在末次已知未发生结局的时点截断观察', '只用于生存或时间-事件分析里“此后不知结局”。临床失访是 lost to follow-up，不要互相替换。'),
  ('4a6e9677-80c4-5f6c-bced-b3b97993e51f', 'research_english:statistics_methodology:hazard:noun', 'fc3275ea-8cc5-568c-a828-4483ab412e93', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2ea63ebe-26b8-5460-b60d-663b588b828e', 'the instantaneous rate at which an event occurs among those still at risk', '风险率；瞬时事件发生率', '谈的是仍处在风险集中的人在某一瞬间的事件率。不是普通“危险”，也不等于累计发病率。'),
  ('ad68d2ba-709d-57ff-941f-e2ac040993fa', 'research_english:statistics_methodology:intention-to-treat:noun', 'f388359f-9c19-56f2-b2a7-151fb132126d', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2ea63ebe-26b8-5460-b60d-663b588b828e', 'an analysis that keeps participants in the groups to which they were randomized', '意向性治疗分析；按随机分组分析', '按当初随机到的组来分析，不管后来有没有按方案治疗。as-treated 更窄，不要写成已经证明药效。'),
  ('d94c7a99-df3a-52f4-b0ea-8321786d3ef6', 'research_english:statistics_methodology:sensitivity-analysis:noun', 'f42239e6-e220-5e65-a9e2-67d521822849', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2ea63ebe-26b8-5460-b60d-663b588b828e', 'a planned re-analysis that checks whether a result holds under different assumptions', '敏感性分析；检验结果是否随假设改变', '换假设或换样本后再算一遍，看结论还在不在。不是探索性挖亚组，也不是主分析本身。'),
  ('d486637d-f6ad-5e00-9aaf-3aee4f8aa5cb', 'research_english:statistics_methodology:selection-bias:noun', '2ef8778c-7830-5f09-9a90-c321e80fce27', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2ea63ebe-26b8-5460-b60d-663b588b828e', 'systematic error from how participants enter, remain in, or are chosen for analysis', '选择偏倚', '谁被选进、留下或拿来分析的方式本身会拧弯结果。普通组间基线不平衡先想 confounding。'),
  ('1299c61f-c062-596f-8128-45f815e24d0c', 'research_english:statistics_methodology:multiplicity:noun', 'ca6dc8f0-bf60-5e7c-a557-7d658b5e3ce8', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2ea63ebe-26b8-5460-b60d-663b588b828e', 'the inflation of false-positive risk that comes from testing many hypotheses', '多重性；多次检验带来的假阳性膨胀', '检验次数多了，偶然显著也会变多。有预先校正或单一主终点时才谈控制 multiplicity。'),
  ('08323eb3-a1aa-5608-a710-c22e9641a849', 'research_english:bioinformatics:doublet:noun', 'e7801c7f-2d2a-5fe1-a9ff-9334911cd942', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2295b0ba-8f8b-5e16-afd8-077f84c8bbc0', 'a single-cell library that actually contains two cells captured together', '双细胞；同一液滴或孔中捕获了两个细胞', '建库时两个细胞被当成一个细胞。不是生物学上的细胞对，过滤后也不要再当真实细胞解释。'),
  ('bdc69b35-80fa-501e-beb9-bd35c1a69fe5', 'research_english:bioinformatics:umi:noun', 'd0703a53-1349-5ae1-a9f0-6739f2d03b43', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2295b0ba-8f8b-5e16-afd8-077f84c8bbc0', 'a random barcode that marks an individual RNA molecule before amplification', '唯一分子标识符；扩增前标记单个 RNA 分子的随机条码', '用来把同一分子的扩增拷贝收成一次计数。没有 UMI 的重复读段不要当成分子数。'),
  ('3ba98e6a-1cd6-5453-ba07-7d987af6123e', 'research_english:bioinformatics:dropout:noun', '496dcf41-0187-5b15-bd97-9e6fe5df15b0', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2295b0ba-8f8b-5e16-afd8-077f84c8bbc0', 'failure to detect an RNA molecule that is present, producing a false zero count', '技术性脱落；分子在却测成零的假阴性', '单细胞里基因没测到，常常是捕获失败，不是细胞真没表达。更不是研究里的失访。'),
  ('37923cde-e08d-561d-8352-947e5afbc7ef', 'research_english:bioinformatics:fdr:noun', '82a588ca-ef82-545b-af83-674a4a1deec5', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2295b0ba-8f8b-5e16-afd8-077f84c8bbc0', 'the expected proportion of false positives among results called significant', '错误发现率；在报显著的结果中预期假阳性所占比例', '管的是“报出来的这些里能有多少是错的”，不是单个检验的 p 值。阈值以下仍可能有假阳性。'),
  ('72c34a5d-5ed3-56a3-bd3b-d6a3d33f68c0', 'research_english:bioinformatics:variant-calling:noun', 'b8ce3812-abfc-5a00-92f0-702176618fac', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2295b0ba-8f8b-5e16-afd8-077f84c8bbc0', 'the computational step that decides which sequence differences are present in a sample', '变异检出；从测序数据判断样本中存在哪些序列差异', '只是算法给出的候选变异。低覆盖或重复区的呼叫要更谨慎，不能直接写成致病突变。'),
  ('8735164a-3c57-5148-9e5f-57a761d60a1d', 'research_english:bioinformatics:adapter:noun', 'cfa3350e-ceaa-57ec-b67e-33ba87187472', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2295b0ba-8f8b-5e16-afd8-077f84c8bbc0', 'a short synthetic sequence ligated to fragments so they can be amplified or sequenced', '接头；接在片段两端以便扩增或测序的人工序列', '文库制备用的测序接头，不是软件接口。残留接头会污染比对，应在分析前去掉。'),
  ('9a39b6e2-43e2-58f3-91e9-f9d711de7aa0', 'research_english:bioinformatics:integration:noun', '9add02fa-75f1-576a-9b1e-f34010b327cb', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2295b0ba-8f8b-5e16-afd8-077f84c8bbc0', 'joint embedding of cells or samples from different datasets after reducing batch-driven separation', '整合；在减弱批次分离后把不同数据集合到同一表示中', '把多个单细胞或组学数据集放到可比较的空间里。不是数学积分，也不能保证生物学差异都被保住。'),
  ('4a2d5286-cd54-5c51-9e0d-7881fd2dbb4d', 'research_english:bioinformatics:annotation:noun', 'dfbed82c-4158-56fb-a052-ccb5dd0da597', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2295b0ba-8f8b-5e16-afd8-077f84c8bbc0', 'the assigned biological labels for genomic features such as genes, transcripts, or variants', '注释；为基因、转录本或变异等基因组特征赋予的生物学标签', '参考数据库给出的位置和功能标签，会随版本更新。不要把注释写成实验测到的功能。'),
  ('b47a322c-b9e1-5e0d-91f1-087d367ba222', 'research_english:bioinformatics:haplotype:noun', 'ecc77ec4-c391-5891-a152-30974f6a70dc', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2295b0ba-8f8b-5e16-afd8-077f84c8bbc0', 'a set of variants inherited together on one chromosome copy', '单倍型；同一条染色体拷贝上连锁遗传的一组变异', '一条染色体上一起传下去的等位组合。基因型是两个单倍型的无序对，不要互相替换。'),
  ('5833660d-1c58-5ad1-9a6e-13ba71675ced', 'medical_english:anatomy:stenosis:noun', '61285a19-efb3-5951-a5de-48f24cc1b2a7', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'f2f95a33-ad8a-576c-9ec4-563e8ad57801', 'abnormal narrowing of a lumen such as a vessel, valve, or canal', '狭窄；管腔异常变窄', '管腔比正常窄，要写清部位和程度。不是管壁增厚本身，也不等于已经缺血。'),
  ('6e00a386-2fce-51c3-bc4f-891a524b90b6', 'medical_english:anatomy:parenchyma:noun', '06ad97fc-0c17-5aac-a2d2-de88d619bcd6', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'f2f95a33-ad8a-576c-9ec4-563e8ad57801', 'the functional tissue of an organ, as distinct from its supporting framework', '实质；器官发挥功能的组织，有别于支架结构', '指肝、肺、肾等真正做事的组织。包膜、血管或间质支架不要写成 parenchyma。'),
  ('74ef824c-1ed8-51bc-87a4-814c8bdc9b99', 'medical_english:physiology:homeostasis:noun', 'c3e1ff13-f5f4-5d1c-9230-42bb883e841b', '52d53e9d-b343-50d9-b0d8-059b2540f890', '0419c1eb-5b7b-5fdc-aacb-c4daf1afd345', 'active maintenance of a stable internal environment within a narrow range', '稳态；把内环境主动维持在狭窄范围内', '是主动调节后的稳定，不是“什么都没变”。一次实验室值正常也不等于稳态已恢复。'),
  ('f8fa9c94-2f24-5f2f-8ea7-8840bf9d3c47', 'medical_english:physiology:preload:noun', '9c95e6ff-7d17-5b15-b37e-b1652367c68c', '52d53e9d-b343-50d9-b0d8-059b2540f890', '0419c1eb-5b7b-5fdc-aacb-c4daf1afd345', 'the ventricular wall stretch at the end of filling, reflecting venous return', '前负荷；心室充盈末期的壁伸展，反映回心血量', '泵血前心室被充了多少。afterload 是泵血时要克服的阻力，二者不要对调。'),
  ('25388f32-1771-56ea-b9f9-16a3a141e5eb', 'medical_english:pathology:ischemia:noun', 'af84428a-6467-5752-ae64-3d611c23ca86', '52d53e9d-b343-50d9-b0d8-059b2540f890', '3f8e08d5-d603-52c6-a794-038712ff8d03', 'inadequate blood flow that leaves tissue short of oxygen and nutrients', '缺血；血流不足以供应组织氧和营养', '组织还没死，只是供血不够。梗死是缺血持续后的坏死，不要提前写成 infarction。'),
  ('ef71c22b-e0b6-54bd-8c54-858b531f867f', 'medical_english:pathology:dysplasia:noun', 'f1b6b931-cbd7-5e3f-857a-d7257f8dcb9a', '52d53e9d-b343-50d9-b0d8-059b2540f890', '3f8e08d5-d603-52c6-a794-038712ff8d03', 'disordered cell growth and architecture that is not yet invasive cancer', '发育异常；细胞生长和结构紊乱但尚未浸润', '形态已经乱，但还不是浸润癌。炎症修复或单纯增生不要随口写成 dysplasia。'),
  ('059f159e-5e63-544e-835f-1443d03f1e2f', 'medical_english:symptoms:syncope:noun', 'a3e6cbfe-c998-5fe3-81c8-a966ade050e5', '52d53e9d-b343-50d9-b0d8-059b2540f890', '58a9e7bc-4a47-5465-bf8e-a6312ab0df40', 'a brief, self-limited loss of consciousness from transient cerebral hypoperfusion', '晕厥；因一过性脑灌注不足导致的短暂意识丧失', '真的短暂失去意识后又自己恢复。头昏或要摔倒但没失去意识不要写成 syncope。'),
  ('836bdfa3-3ad6-5d78-b126-f2d4eda30c9e', 'medical_english:symptoms:orthopnea:noun', '31eba216-6c00-58ff-87c1-77403d9e0f14', '52d53e9d-b343-50d9-b0d8-059b2540f890', '58a9e7bc-4a47-5465-bf8e-a6312ab0df40', 'breathlessness that appears or worsens when the patient lies flat', '端坐呼吸；平卧时出现或加重的气促', '平躺就喘、坐起好转。夜间阵发性呼吸困难是睡着后再憋醒，不要和这一条混成一个词。'),
  ('311a586b-21a3-5225-b1fd-f6aa4491d796', 'medical_english:symptoms:cachexia:noun', '18d88136-f0bb-5573-b414-a7d6847aa4a5', '52d53e9d-b343-50d9-b0d8-059b2540f890', '58a9e7bc-4a47-5465-bf8e-a6312ab0df40', 'severe, illness-related wasting of muscle and weight that is not explained by fasting alone', '恶病质；疾病相关的显著肌肉和体重消耗', '慢性病引起的消耗，不是单纯几天没吃饱。普通体重下降先写 weight loss。'),
  ('7b748aa4-4250-5441-8d65-e0f95890a7b1', 'medical_english:signs:ascites:noun', '5216cd72-f7e4-52da-932d-3f6cad11f93f', '52d53e9d-b343-50d9-b0d8-059b2540f890', '55cae568-79b1-56b4-89eb-8a24ade01c2a', 'abnormal accumulation of fluid in the peritoneal cavity', '腹水；腹腔内异常积液', '查体或影像确认腹腔里有游离液体。腹胀本身不够，也不等于已经是肝硬化。'),
  ('3e469404-e130-5ff1-b790-6bfe64bc674b', 'medical_english:signs:lymphadenopathy:noun', '73ea2fba-1422-5424-b0b8-ab563875a76b', '52d53e9d-b343-50d9-b0d8-059b2540f890', '55cae568-79b1-56b4-89eb-8a24ade01c2a', 'enlarged lymph nodes detected on examination or imaging', '淋巴结肿大', '淋巴结比正常大，要写部位。摸到肿块但不确定是淋巴结时，先别写成 lymphadenopathy。'),
  ('1ba8b16d-7891-5113-81bb-4da870ac98aa', 'medical_english:diseases:sepsis:noun', 'ee9080de-5a45-5bb6-a9c4-56a37d5d2849', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'a2d7ba65-5cfb-5646-b038-c803f92f88bb', 'life-threatening organ dysfunction caused by a dysregulated response to infection', '脓毒症；感染引发的失控宿主反应并导致器官功能障碍', '有感染加上器官功能变差。菌血症或单纯发热还不到 sepsis，也不要用它代替具体感染灶。'),
  ('61f5a034-6d94-5052-bcf7-3f93b3c39945', 'medical_english:diseases:embolism:noun', 'e970db39-d28d-5dba-a31e-691f4caab339', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'a2d7ba65-5cfb-5646-b038-c803f92f88bb', 'sudden blockage of a vessel by material carried from elsewhere in the circulation', '栓塞；循环中的栓子突然堵住血管', '栓子从别处漂来堵住血管。血栓形成在原位，血栓形成和栓塞不要混成一个词。'),
  ('cd5c16ef-bb60-5dbb-b645-1e4f6e8636d4', 'medical_english:diagnosis:pathogenesis:noun', '5e2fcace-e169-57ae-91d2-3420cc06f972', '52d53e9d-b343-50d9-b0d8-059b2540f890', '418fd2cc-1b52-52cd-a6b1-460558fc0fad', 'the sequence of biological events by which a disease develops', '发病机制；疾病逐步形成的生物学过程', '问疾病怎么一步步发展。etiology 问的是什么原因引起，二者不要对调。'),
  ('a4e0ba58-1b2c-576f-8e95-e698b74954f5', 'medical_english:diagnosis:idiopathic:adjective', '2d34d8f0-2ee8-5ba8-80f9-3e96edc55e9a', '52d53e9d-b343-50d9-b0d8-059b2540f890', '418fd2cc-1b52-52cd-a6b1-460558fc0fad', 'arising without an identified cause after reasonable evaluation', '特发的；在合理检查后仍找不到病因的', '查过了仍不知道原因才叫 idiopathic。还没查完用 unknown；治疗引起的是 iatrogenic。'),
  ('4d3b6ec4-b93e-5a4c-be93-8e6a45f5c5ef', 'medical_english:diagnosis:iatrogenic:adjective', '74a210d1-5615-5450-9f48-49dfc96369e2', '52d53e9d-b343-50d9-b0d8-059b2540f890', '418fd2cc-1b52-52cd-a6b1-460558fc0fad', 'caused by a diagnostic or therapeutic intervention rather than by the original disease', '医源性的；由诊疗操作引起，而非原发病本身', '问题来自检查或治疗。特发是找不到原因；并发症若能明确追到操作，用 iatrogenic 更准。'),
  ('30dd3e35-65f8-5d9c-8398-d524e816cb95', 'medical_english:laboratory:thrombocytopenia:noun', '627cd0ac-0a55-5a56-9c2f-ce836afc4166', '52d53e9d-b343-50d9-b0d8-059b2540f890', '10e2306a-068b-5b0d-be9c-deb0606e5aae', 'a platelet count below the reference range', '血小板减少', '化验上血小板低于参考范围。它本身不是出血诊断，假性减少要先排除标本凝块。'),
  ('608c8110-6aa9-511f-b646-b88b4b849549', 'medical_english:laboratory:transaminitis:noun', '4d88c44d-1810-59da-8b77-6241b5f4184c', '52d53e9d-b343-50d9-b0d8-059b2540f890', '10e2306a-068b-5b0d-be9c-deb0606e5aae', 'informal laboratory shorthand for elevated aminotransferase levels', '转氨酶升高（非正式化验说法）', '病历里对 ALT/AST 升高的简称，不是独立疾病。写论文或出院诊断时更宜写 elevated transaminases。'),
  ('b6a38dc9-5da8-55b5-a601-2aab852b4370', 'medical_english:imaging:effusion:noun', 'eaaa062d-a18e-5eea-bc41-44464306b281', '52d53e9d-b343-50d9-b0d8-059b2540f890', '9f6cc5fa-eecd-5d8c-afa7-4ad74c8e4d2e', 'abnormal fluid collected in a body cavity, described on imaging or examination', '积液；体腔内异常聚集的液体', '腔隙里多了液体这一影像或体征，不是炎症诊断。腹水是腹膜腔积液的临床说法，胸腔仍写 effusion。'),
  ('a18702ff-8bd9-5010-a03f-f95fbd407965', 'medical_english:imaging:infiltrate:noun', '340ffb6a-2956-5143-b98c-354ef8f0dc4f', '52d53e9d-b343-50d9-b0d8-059b2540f890', '9f6cc5fa-eecd-5d8c-afa7-4ad74c8e4d2e', 'a poorly defined area of increased lung density that may represent filling of airspace or interstitium', '浸润影；肺野内边界不清的密度增高区', '影像描述，不是肺炎诊断。比 opacity 更暗示物质进入气腔或间质，但仍不能直接写成感染。'),
  ('3656df7d-4338-56cc-8d05-0b3fc8dff5cc', 'medical_english:treatment:empiric:adjective', '099d64e7-3d4b-599a-a482-6fc213137ecb', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'd1c91e1b-3970-5d28-9e17-446cc90b1388', 'started on likely pathogens or usual practice before confirmatory results are back', '经验性的；在确诊结果回报前按常见情况先治', '培养或药敏还没回来就先覆盖最可能的情况。针对性治疗是 targeted，二者不要对调。'),
  ('2f78a5f1-0b6a-5b8c-9fd7-119795c6c8d7', 'medical_english:treatment:prophylaxis:noun', 'abbbc051-729f-5a80-a626-a7349073a093', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'd1c91e1b-3970-5d28-9e17-446cc90b1388', 'treatment given to prevent a disease or complication rather than to treat it after it appears', '预防；预防性用药或措施', '事情还没发生时用来防止它发生。已经在治活动性疾病就不是 prophylaxis。'),
  ('52fef1fa-7fc8-5667-bcbd-69aa623442e8', 'medical_english:treatment:adjuvant:adjective', '38478f4d-2ee4-5046-860e-264f2aec9126', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'd1c91e1b-3970-5d28-9e17-446cc90b1388', 'given after definitive local treatment to lower the risk of recurrence', '辅助的；根治性局部治疗后为降低复发风险而加用的', '手术或放疗之后再补上的全身治疗。新辅助是做之前，转移灶的解救治疗也不是 adjuvant。'),
  ('b91c854c-3d81-5891-bed0-54b952cf0244', 'medical_english:pharmacology:half-life:noun', '78d79d7e-3fc1-51e7-a441-07e68a67331f', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'be176af9-cee2-5fc3-a8c1-dabaf200bb70', 'the time required for the amount of drug in the body to fall by half', '半衰期；体内药量降至一半所需时间', '浓度大约降一半的时间，用来安排给药间隔。作用持续时间可以更长或更短，不要划等号。'),
  ('b60ab1b2-ed67-58d8-af81-4a482b4d5364', 'medical_english:pharmacology:agonist:noun', 'f8d4d2b2-b10c-5860-aa51-beee16a1ef4f', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'be176af9-cee2-5fc3-a8c1-dabaf200bb70', 'a ligand that binds a receptor and activates it', '激动剂；与受体结合并激活它的配体', '结合并且打开这条通路。拮抗剂是占着位置不激活，不要写成相反的药。'),
  ('cc430fba-84ac-58d0-b6a8-efd08164b3ec', 'medical_english:surgery_procedures:resection:noun', '8ca21a52-e7a8-5491-b9f2-40b0e40773f4', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'fa342f3d-0091-5406-a280-66eb64166d92', 'surgical removal of part or all of an organ or lesion', '切除；手术去除器官或病变的一部或全部', '组织被切下来。单纯切开探查或造口还不到 resection；活检只取一小块。'),
  ('38c7a8cd-e47b-5754-8f7e-082656255219', 'medical_english:surgery_procedures:ligation:noun', '46b77cdf-e318-5e80-bd53-7b3e3db85dd9', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'fa342f3d-0091-5406-a280-66eb64166d92', 'tying or clipping a vessel or duct to occlude it', '结扎；把血管或导管扎闭', '用线或夹子把管道扎住。切断是 transection，缝合对合是 anastomosis，不要混用。'),
  ('1c993255-236c-591e-b7b8-77dc26033747', 'medical_english:clinical_expressions:present-with:phrasal-verb', 'c3329f63-0ad6-53c9-9cc8-da9e953966c7', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'a482bbf8-c44c-590c-a328-562f923f69ae', 'to come to medical attention already having the stated symptoms or findings', '以……为主诉或表现为……就诊', '记录患者来时带着哪些表现。不是“赠送”或普通 appear；确诊后的病程进展也不要用它开头。'),
  ('e2aae7e9-77a0-57ab-a146-7fb6a1d00d93', 'medical_english:clinical_expressions:hemodynamically-stable:adjective', '248d714e-fefa-51a8-8fbf-eaeb2d1e0a0d', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'a482bbf8-c44c-590c-a328-562f923f69ae', 'having blood pressure and perfusion adequate to support organ function at the moment of assessment', '血流动力学稳定；当时血压和灌注尚能维持器官功能', '只保证循环数字和灌注当时够用。一般情况尚可或神志清楚都代替不了这一条。'),
  ('be3ae221-3f50-5216-867f-748128f4e561', 'medical_english:clinical_expressions:status-post:phrase', '629c3dc3-9aae-50d2-ad8e-a913995114fa', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'a482bbf8-c44c-590c-a328-562f923f69ae', 'currently in the state that follows a named procedure or event', '……术后/事后状态；处于某操作或事件之后', '病历缩写，说明当前处在某手术或事件之后。不要写成正在做手术，也不要用它代替完整手术史叙述。')
insert into public.contexts (id, stable_key, word_sense_id, context_sentence, target_text, plain_english_paraphrase, sentence_translation_zh, collocations, context_genre, source_type, source_title, source_url, doi, pmid)
values
  ('0d54b9d2-2b65-520b-b417-0f78fa21c062', 'research_english:general_research:implicate:verb:res-general-implicate-001', 'cb8e5a9f-f438-526d-a828-364107d05149', 'These expression changes implicate interferon signaling in the early response to infection.', 'implicate', 'The expression pattern points to interferon signaling as part of the early response, without proving it is the cause.', '这些表达变化提示干扰素信号可能参与感染的早期应答。', array['implicate a pathway', 'implicate a mechanism', 'findings implicate']::text[], 'research_results', 'original_example', null, null, null, null),
  ('5dde15ad-9134-5aae-8fb9-24dbb937fb3c', 'research_english:general_research:preclude:verb:res-general-preclude-001', '3b5e0527-6d56-5388-b8cc-a97cdf46a9a5', 'The absence of pretreatment samples precludes any claim about the direction of change.', 'precludes', 'Because there were no samples before treatment, the study cannot say whether the values rose or fell.', '缺少治疗前样本，因此无法就变化方向作出任何判断。', array['preclude causal inference', 'preclude a firm conclusion', 'sample size precludes']::text[], 'research_discussion', 'original_example', null, null, null, null),
  ('9269b000-fe1d-53ec-b4b7-4ef5ff61862b', 'research_english:general_research:mediate:verb:res-general-mediate-001', '28eb0fd6-ba27-5346-b7b4-03ff4523598f', 'The treatment effect on fatigue was partly mediated by the improvement in sleep quality.', 'mediated', 'Part of the reduction in fatigue appeared to occur because sleep quality improved.', '治疗对疲劳的效应有一部分由睡眠质量改善所介导。', array['mediated by', 'partially mediated', 'mediate the effect']::text[], 'research_results', 'original_example', null, null, null, null),
  ('24c2d8bc-fdac-51af-baf0-4d871bfff8ba', 'research_english:general_research:mitigate:verb:res-general-mitigate-001', 'ce18c099-ce07-5688-8b46-eb192373aac4', 'Duplicate review of eligibility decisions was used to mitigate misclassification of cases.', 'mitigate', 'Two reviewers checked who qualified for the study so that fewer people would be labeled incorrectly.', '通过对入选决定进行双人复核，以减轻病例错分。', array['mitigate bias', 'mitigate risk', 'mitigate a limitation']::text[], 'research_methods', 'original_example', null, null, null, null),
  ('a4823760-9b0d-5831-a9b2-2ccbeca347d4', 'research_english:general_research:substantiate:verb:res-general-substantiate-001', '90ac5257-05bd-5870-8fb8-3807189f5502', 'Independent replication in two cohorts helped substantiate the proposed risk association.', 'substantiate', 'Seeing the same risk pattern in two separate groups made the proposed association more credible.', '在两个队列中的独立重复有助于证实所提出的风险关联。', array['substantiate a claim', 'substantiate a finding', 'help substantiate']::text[], 'research_discussion', 'original_example', null, null, null, null),
  ('85f12d2c-c3ca-5fd7-8cf3-2fe2ab012e91', 'research_english:general_research:putative:adjective:res-general-putative-001', '3620b02c-dda4-55bd-bd39-9480a6d4afd5', 'The receptor is a putative regulator of T-cell exhaustion, although functional data remain limited.', 'putative', 'Researchers currently treat the receptor as a possible controller of T-cell exhaustion, but that role is not yet shown.', '该受体被当作 T 细胞耗竭的推定调节因子，但功能证据仍然有限。', array['putative mechanism', 'putative role', 'putative target']::text[], 'research_introduction', 'original_example', null, null, null, null),
  ('e058e59d-89e4-58fa-8b80-d53ce531ce14', 'research_english:general_research:modest:adjective:res-general-modest-001', 'a67220c9-38c7-591d-a9d1-5408625800a1', 'Weight declined by a modest 1.4 kilograms, with little change in waist circumference.', 'modest', 'People lost only a small amount of weight, and waist size barely changed.', '体重仅小幅下降 1.4 千克，腰围几乎没有变化。', array['modest effect', 'modest improvement', 'modest difference']::text[], 'research_results', 'original_example', null, null, null, null),
  ('32c2af4c-829a-58de-9f25-d1b730f518e2', 'research_english:general_research:constrain:verb:res-general-constrain-001', 'bd4e1861-270c-50fe-942c-a81d70afaa0c', 'Sparse longitudinal sampling constrained our ability to date the onset of resistance.', 'constrained', 'Because samples were taken too infrequently, the team could not pin down when resistance first appeared.', '纵向采样稀疏，限制了我们判定耐药出现时间的能力。', array['constrain interpretation', 'constrained by sample size', 'tightly constrained']::text[], 'research_discussion', 'original_example', null, null, null, null),
  ('2156b44a-d33b-5a80-885a-872b0a4c6f0e', 'research_english:general_research:confound:verb:res-general-confound-001', 'c96931aa-afbe-542b-b631-0a3e4c4351b7', 'Differences in smoking history may confound the association between coffee intake and stroke.', 'confound', 'If smokers also drink different amounts of coffee, smoking could make the coffee–stroke link look stronger or weaker than it is.', '吸烟史的差异可能混淆咖啡摄入与卒中之间的关联。', array['confound an association', 'confound the comparison', 'potentially confound']::text[], 'research_discussion', 'original_example', null, null, null, null),
  ('7cb0b126-3853-5084-9801-3cdbf1951960', 'research_english:general_research:plausible:adjective:res-general-plausible-001', 'dfa100f3-7fb1-51a0-bd1f-3daf196598f0', 'A shared inflammatory pathway is a plausible explanation for the two clinical observations.', 'plausible', 'One inflammation pathway could reasonably account for both findings, although that has not been shown.', '共同的炎症通路是对这两项临床观察的一种看似合理的解释。', array['plausible mechanism', 'biologically plausible', 'plausible explanation']::text[], 'research_discussion', 'original_example', null, null, null, null),
  ('c298f276-1923-5411-87e1-908e99518ab6', 'research_english:general_research:tentative:adjective:res-general-tentative-001', '2dcadd58-022e-5d3c-8cf0-a256acb1fc78', 'Any recommendation based on this single-center series should remain tentative.', 'tentative', 'Because the cases all came from one hospital, any practice advice from them should stay provisional.', '基于这一单中心病例系列提出的任何建议都应保持初步。', array['tentative conclusion', 'tentative evidence', 'remain tentative']::text[], 'research_discussion', 'original_example', null, null, null, null),
  ('1dcc2065-05ab-5888-9013-5e1d377dfc8e', 'research_english:general_research:attributable:adjective:res-general-attributable-001', '591d8b92-57dd-5448-b9cd-1ad39f7afb8a', 'About one third of the excess mortality was attributable to uncontrolled hypertension.', 'attributable', 'After other factors were taken into account, uncontrolled high blood pressure still explained roughly a third of the extra deaths.', '约三分之一的超额死亡可归因于未控制的高血压。', array['attributable to', 'population attributable fraction', 'excess risk attributable']::text[], 'research_results', 'original_example', null, null, null, null),
  ('2900518b-b541-54d6-b858-c7f3a4b69da7', 'research_english:general_research:caveat:noun:res-general-caveat-001', '6bdfe2cf-1a8c-5cd3-bb19-2ce5c1f78768', 'One important caveat is that adherence was self-reported and could not be verified.', 'caveat', 'Readers should remember that patients only said they took the treatment, and that was never checked.', '一个重要的保留条件是依从性由自我报告，无法核实。', array['important caveat', 'interpret with the caveat', 'add a caveat']::text[], 'research_discussion', 'original_example', null, null, null, null),
  ('6c063ff1-6f0d-5e0b-adad-8aa7746f69d9', 'research_english:general_research:abrogate:verb:res-general-abrogate-001', 'c527cce5-d3a7-5bf2-a9cc-305b917c8a81', 'Antibody blockade of the receptor abrogated the protective effect of pretreatment.', 'abrogated', 'Blocking the receptor with an antibody removed the protection that pretreatment had provided.', '用抗体阻断该受体后，预处理的保护效应消失。', array['abrogate an effect', 'abrogate protection', 'completely abrogated']::text[], 'research_results', 'original_example', null, null, null, null),
  ('770017b1-e3e8-54c5-9955-8d991b01a1d3', 'research_english:general_research:underscore:verb:res-general-underscore-001', 'b69dd7a9-5a30-5c7f-bfb4-97f2c539513b', 'The age-related rise in readmission rates underscores the need for earlier follow-up.', 'underscores', 'The higher readmission rates in older patients make earlier follow-up look especially important.', '再入院率随年龄升高，凸显了更早随访的必要。', array['underscore the need', 'underscore the importance', 'findings underscore']::text[], 'research_abstract', 'original_example', null, null, null, null),
  ('824299c2-7b7c-54f3-bc4c-e13455b3b954', 'research_english:statistics_methodology:censor:verb:res-stat-censor-001', '53e70487-eca8-52ff-857a-7fca22c30b70', 'Participants who remained event-free were censored on the date of last contact.', 'censored', 'If no outcome had occurred by the last time the team reached a participant, that person stopped contributing risk time on that date.', '仍未发生结局的参与者在末次联系日期被删失。', array['right-censored data', 'censored at last contact', 'administrative censoring']::text[], 'research_methods', 'original_example', null, null, null, null),
  ('7fa6b422-a0c0-5cdf-96c1-3b281bf0bdbb', 'research_english:statistics_methodology:hazard:noun:res-stat-hazard-001', '4a6e9677-80c4-5f6c-bced-b3b97993e51f', 'The adjusted hazard of hospitalization was 28% lower in the treated group.', 'hazard', 'Among people who had not yet been hospitalized, the instantaneous hospitalization rate was 28% lower after treatment adjustment.', '校正后，治疗组住院的风险率低 28%。', array['hazard ratio', 'cause-specific hazard', 'hazard of death']::text[], 'research_results', 'original_example', null, null, null, null),
  ('e66bcc4f-dbd1-5a79-9d11-f3e8e3687500', 'research_english:statistics_methodology:intention-to-treat:noun:res-stat-intention-to-treat-001', 'ad68d2ba-709d-57ff-941f-e2ac040993fa', 'The primary endpoint was analyzed under the intention-to-treat principle.', 'intention-to-treat', 'Everyone was analyzed in the group assigned at randomization, even if they later switched or stopped treatment.', '主要终点按意向性治疗原则进行分析。', array['intention-to-treat analysis', 'intention-to-treat principle', 'modified intention-to-treat']::text[], 'research_methods', 'original_example', null, null, null, null),
  ('e52bc7cc-92c5-5433-9fc1-a76c283cf0fe', 'research_english:statistics_methodology:sensitivity-analysis:noun:res-stat-sensitivity-analysis-001', 'd94c7a99-df3a-52f4-b0ea-8321786d3ef6', 'A sensitivity analysis that excluded late enrollees left the treatment estimate unchanged.', 'sensitivity analysis', 'Repeating the analysis without people who joined late did not change the estimated treatment effect.', '排除晚期入组者后的敏感性分析未改变治疗效应估计。', array['pre-specified sensitivity analysis', 'sensitivity analysis excluding', 'results of the sensitivity analysis']::text[], 'supplementary_methods', 'original_example', null, null, null, null),
  ('3e364f4f-df4c-551a-a216-9ed37caaed82', 'research_english:statistics_methodology:selection-bias:noun:res-stat-selection-bias-001', 'd486637d-f6ad-5e00-9aaf-3aee4f8aa5cb', 'Online recruitment may introduce selection bias if healthier adults are more likely to enroll.', 'selection bias', 'If healthier people are more willing to join an online study, the sample may not represent the intended population.', '若更健康的成人更可能报名，线上招募就可能引入选择偏倚。', array['introduce selection bias', 'vulnerable to selection bias', 'minimize selection bias']::text[], 'research_discussion', 'original_example', null, null, null, null),
  ('f8689548-5a1c-56de-968e-8545fb0372a0', 'research_english:statistics_methodology:multiplicity:noun:res-stat-multiplicity-001', '1299c61f-c062-596f-8128-45f815e24d0c', 'The statistical plan specified a hierarchical test to control multiplicity across endpoints.', 'multiplicity', 'Endpoints were tested in a pre-set order so that looking at several outcomes would not freely inflate false-positive findings.', '统计计划规定用层级检验来控制各终点之间的多重性。', array['control for multiplicity', 'multiplicity adjustment', 'multiplicity of testing']::text[], 'research_methods', 'original_example', null, null, null, null),
  ('b023dd2c-9cd5-593b-b820-9b848ba6c9f4', 'research_english:bioinformatics:doublet:noun:res-bio-doublet-001', '08323eb3-a1aa-5608-a710-c22e9641a849', 'Libraries with unusually high gene counts were flagged as likely doublets and removed.', 'doublets', 'Libraries that detected far more genes than usual were treated as two cells captured together and discarded.', '基因检出数异常高的文库被标为可能的双细胞并被去除。', array['remove doublets', 'doublet detection', 'likely doublets']::text[], 'research_methods', 'original_example', null, null, null, null),
  ('b1a4eccf-e823-551e-a045-dba79735288c', 'research_english:bioinformatics:umi:noun:res-bio-umi-001', 'bdc69b35-80fa-501e-beb9-bd35c1a69fe5', 'Reads that shared the same cell barcode and UMI were collapsed before counting.', 'UMI', 'Duplicate copies that came from one RNA molecule in one cell were counted only once.', '共享同一细胞条码和 UMI 的读段在计数前被合并。', array['UMI count', 'UMI collapsing', 'unique molecular identifier']::text[], 'supplementary_methods', 'original_example', null, null, null, null),
  ('b7b942d4-4fb1-568b-8b8a-ccb5ea9e9e41', 'research_english:bioinformatics:dropout:noun:res-bio-dropout-001', '3ba98e6a-1cd6-5453-ba07-7d987af6123e', 'Zero counts were treated as a mixture of true absence and technical dropout.', 'dropout', 'A zero could mean the gene was truly off, or that the molecule was present but missed by the assay.', '零计数被当作真实缺失与技术性脱落的混合结果。', array['technical dropout', 'dropout event', 'account for dropout']::text[], 'research_methods', 'original_example', null, null, null, null),
  ('f499b6d8-5e65-526b-bb2e-3e22a7971032', 'research_english:bioinformatics:fdr:noun:res-bio-fdr-001', '37923cde-e08d-561d-8352-947e5afbc7ef', 'Genes with an FDR below 0.05 were reported as differentially expressed.', 'FDR', 'A gene was listed as different between conditions only if the expected share of false calls among such genes stayed under 5%.', '错误发现率低于 0.05 的基因被报告为差异表达。', array['FDR threshold', 'control the FDR', 'FDR-adjusted p value']::text[], 'research_results', 'original_example', null, null, null, null),
  ('c1618e7a-2e02-510c-8f43-b8771d274e6e', 'research_english:bioinformatics:variant-calling:noun:res-bio-variant-calling-001', '72c34a5d-5ed3-56a3-bd3b-d6a3d33f68c0', 'Sites with coverage below twenty-fold were excluded from variant calling.', 'variant calling', 'The software was not asked to decide whether a variant was present if fewer than twenty reads covered that site.', '覆盖深度低于 20 倍的位点不纳入变异检出。', array['germline variant calling', 'variant calling pipeline', 'joint variant calling']::text[], 'research_methods', 'original_example', null, null, null, null),
  ('1a7f15dc-ab04-5351-8c64-39951c53a04a', 'research_english:bioinformatics:adapter:noun:res-bio-adapter-001', '8735164a-3c57-5148-9e5f-57a761d60a1d', 'Trailing adapter sequence was trimmed from reads before alignment.', 'adapter', 'Artificial tail sequences added during library preparation were cut off before the reads were matched to the genome.', '比对前先从读段中修剪掉末端接头序列。', array['adapter sequence', 'adapter trimming', 'adapter contamination']::text[], 'supplementary_methods', 'original_example', null, null, null, null),
  ('c35ad85d-4df5-5047-a1d4-27312dd1af97', 'research_english:bioinformatics:integration:noun:res-bio-integration-001', '9a39b6e2-43e2-58f3-91e9-f9d711de7aa0', 'After integration, cells from the two platforms occupied overlapping regions of the embedding.', 'integration', 'Once the two datasets were placed in a shared space, cells no longer sat in separate clouds just because they were generated on different platforms.', '整合后，来自两个平台的细胞在嵌入空间中占据了重叠区域。', array['dataset integration', 'batch integration', 'single-cell integration']::text[], 'research_methods', 'original_example', null, null, null, null),
  ('838fe6c5-702e-5b41-96dd-4bfc4e9618d2', 'research_english:bioinformatics:annotation:noun:res-bio-annotation-001', '4a2d5286-cd54-5c51-9e0d-7881fd2dbb4d', 'Gene names in the heatmap follow the GENCODE gene annotation used for this analysis.', 'annotation', 'The heatmap uses gene names from the GENCODE catalog chosen for this study, not from a different annotation set.', '热图中的基因名遵循本次分析所用的 GENCODE 基因注释。', array['genome annotation', 'gene annotation', 'annotation version']::text[], 'figure_legend', 'original_example', null, null, null, null),
  ('91cf5a20-e85f-56e6-8307-e4c8e82ecd7b', 'research_english:bioinformatics:haplotype:noun:res-bio-haplotype-001', 'b47a322c-b9e1-5e0d-91f1-087d367ba222', 'The risk haplotype carried both the promoter variant and the coding substitution.', 'haplotype', 'On the same chromosome copy, the promoter change and the coding change were inherited together in the higher-risk version.', '该风险单倍型同时携带启动子变异和编码区替换。', array['risk haplotype', 'haplotype frequency', 'phased haplotype']::text[], 'research_results', 'original_example', null, null, null, null),
  ('57973b05-1e2a-5c72-bbfb-2f18449ef074', 'medical_english:anatomy:stenosis:noun:med-anatomy-stenosis-001', '5833660d-1c58-5ad1-9a6e-13ba71675ced', 'Computed tomography showed high-grade stenosis of the proximal left anterior descending artery.', 'stenosis', 'The scan found severe narrowing near the start of a major artery on the front of the left heart.', 'CT 显示左前降支近段重度狭窄。', array['high-grade stenosis', 'aortic stenosis', 'luminal stenosis']::text[], 'imaging_report', 'original_example', null, null, null, null),
  ('0c5e3563-afb1-5c1f-a6ca-110f02960727', 'medical_english:anatomy:parenchyma:noun:med-anatomy-parenchyma-001', '6e00a386-2fce-51c3-bc4f-891a524b90b6', 'Most of the kidney''s filtering work occurs in the renal parenchyma rather than in the collecting system.', 'parenchyma', 'Urine is filtered in the working tissue of the kidney, not in the drainage passages that collect it.', '肾脏的大部分滤过工作发生在肾实质，而不是集合系统。', array['renal parenchyma', 'hepatic parenchyma', 'parenchymal tissue']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('fe5638d0-e336-545a-bb29-e9684c9d0790', 'medical_english:physiology:homeostasis:noun:med-physiology-homeostasis-001', '74ef824c-1ed8-51bc-87a4-814c8bdc9b99', 'Aldosterone helps maintain sodium homeostasis when dietary intake falls.', 'homeostasis', 'When people eat less salt, aldosterone helps keep body sodium from drifting too low.', '饮食钠摄入下降时，醛固酮有助于维持钠稳态。', array['maintain homeostasis', 'glucose homeostasis', 'disrupted homeostasis']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('1ead52e3-f0bf-50e0-bc0b-4d380f10613c', 'medical_english:physiology:preload:noun:med-physiology-preload-001', 'f8fa9c94-2f24-5f2f-8ea7-8840bf9d3c47', 'Diuretics were reduced to preserve preload in the patient with right ventricular infarction.', 'preload', 'Water pills were cut back so that enough blood still filled the damaged right ventricle before each beat.', '对右心室梗死患者减少利尿剂，以保留前负荷。', array['reduce preload', 'adequate preload', 'preload dependence']::text[], 'clinical_guideline', 'original_example', null, null, null, null),
  ('bf290c15-c84f-537d-a864-71e2c3f4e700', 'medical_english:pathology:ischemia:noun:med-pathology-ischemia-001', '25388f32-1771-56ea-b9f9-16a3a141e5eb', 'Transient mesenteric ischemia can cause severe pain before bowel infarction develops.', 'ischemia', 'A shortfall of blood flow to the gut can hurt badly even before the bowel tissue has died.', '短暂的肠系膜缺血可在肠梗死出现前就引起剧痛。', array['myocardial ischemia', 'cerebral ischemia', 'reversible ischemia']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('38a358e7-1042-5647-a9bb-5ed516b287cf', 'medical_english:pathology:dysplasia:noun:med-pathology-dysplasia-001', 'ef71c22b-e0b6-54bd-8c54-858b531f867f', 'Biopsy of the cervical lesion showed high-grade dysplasia without stromal invasion.', 'dysplasia', 'The cervical sample showed severely disordered cells, but they had not grown into the supporting tissue.', '宫颈病变活检显示高级别上皮内瘤变/发育异常，未见间质浸润。', array['high-grade dysplasia', 'epithelial dysplasia', 'dysplastic cells']::text[], 'case_report', 'original_example', null, null, null, null),
  ('2779263a-1ca4-557d-829c-91cb1f93eb90', 'medical_english:symptoms:syncope:noun:med-symptoms-syncope-001', '059f159e-5e63-544e-835f-1443d03f1e2f', 'He had a witnessed syncope while standing in line and regained awareness within a minute.', 'syncope', 'He briefly passed out while standing, and someone saw him recover within a minute.', '他在排队站立时发生目击下晕厥，约一分钟内意识恢复。', array['witnessed syncope', 'exertional syncope', 'recurrent syncope']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('d25f14ec-a7ec-5d10-9bbd-89e42d9ceb7b', 'medical_english:symptoms:orthopnea:noun:med-symptoms-orthopnea-001', '836bdfa3-3ad6-5d78-b126-f2d4eda30c9e', 'She developed orthopnea and began sleeping on two pillows to stay upright.', 'orthopnea', 'She became short of breath when lying flat and started using two pillows to keep her chest raised.', '她出现端坐呼吸，并开始垫两个枕头半卧睡觉。', array['report orthopnea', 'worsening orthopnea', 'orthopnea and edema']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('dba07427-8d3f-5bcc-b383-b230ce614e05', 'medical_english:symptoms:cachexia:noun:med-symptoms-cachexia-001', '311a586b-21a3-5225-b1fd-f6aa4491d796', 'Progressive cachexia developed over three months despite continued oral intake.', 'cachexia', 'He kept losing muscle and weight for three months even though he was still eating.', '尽管仍能经口进食，三个月来仍出现进行性恶病质。', array['cancer cachexia', 'progressive cachexia', 'cachexia and anorexia']::text[], 'case_report', 'original_example', null, null, null, null),
  ('9c8224c4-23a9-5d33-bf33-24e31c28be5c', 'medical_english:signs:ascites:noun:med-signs-ascites-001', '7b748aa4-4250-5441-8d65-e0f95890a7b1', 'Shifting dullness and a fluid wave were consistent with moderate ascites.', 'ascites', 'The abdominal exam suggested a moderate amount of free fluid in the belly.', '移动性浊音和液波震颤符合中等量腹水。', array['tense ascites', 'refractory ascites', 'new-onset ascites']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('b945818a-4c13-5325-9006-87e25144b863', 'medical_english:signs:lymphadenopathy:noun:med-signs-lymphadenopathy-001', '3e469404-e130-5ff1-b790-6bfe64bc674b', 'Tender cervical lymphadenopathy was present on the same side as the pharyngitis.', 'lymphadenopathy', 'Enlarged, tender neck nodes were found on the same side as the sore throat.', '咽炎同侧可触及压痛性颈部淋巴结肿大。', array['cervical lymphadenopathy', 'generalized lymphadenopathy', 'tender lymphadenopathy']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('592351d3-690c-56b8-b8a8-58b88e9096f8', 'medical_english:diseases:sepsis:noun:med-diseases-sepsis-001', '1ba8b16d-7891-5113-81bb-4da870ac98aa', 'Sepsis should be suspected when infection is accompanied by an acute rise in the Sequential Organ Failure Assessment score.', 'Sepsis', 'If a patient has an infection and organ function suddenly worsens on a standard score, treat the picture as sepsis until proven otherwise.', '当感染伴随序贯器官衰竭评估评分急性升高时，应怀疑脓毒症。', array['suspect sepsis', 'sepsis bundle', 'septic shock']::text[], 'clinical_guideline', 'original_example', null, null, null, null),
  ('d34f4b67-8c90-58d9-97d1-ae00650253dd', 'medical_english:diseases:embolism:noun:med-diseases-embolism-001', '61f5a034-6d94-5052-bcf7-3f93b3c39945', 'Acute limb ischemia was attributed to embolism from atrial fibrillation rather than local thrombosis.', 'embolism', 'The sudden loss of blood flow in the limb was thought to come from a clot that traveled out of the heart, not one that formed in the leg artery.', '急性肢体缺血被归因于心房颤动引起的栓塞，而不是局部血栓形成。', array['pulmonary embolism', 'systemic embolism', 'paradoxical embolism']::text[], 'case_report', 'original_example', null, null, null, null),
  ('717debc2-65b0-53eb-b3ef-a97ac03237e4', 'medical_english:diagnosis:pathogenesis:noun:med-diagnosis-pathogenesis-001', 'cd5c16ef-bb60-5dbb-b645-1e4f6e8636d4', 'The pathogenesis of diabetic nephropathy begins with glomerular hyperfiltration and progressive matrix expansion.', 'pathogenesis', 'Diabetic kidney damage develops through a sequence that starts with overfiltering glomeruli and later scar-like matrix buildup.', '糖尿病肾病的发病机制始于肾小球高滤过和基质进行性扩张。', array['disease pathogenesis', 'elucidate the pathogenesis', 'pathogenesis of']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('6be52893-fa08-5b18-82ba-47b45bba462f', 'medical_english:diagnosis:idiopathic:adjective:med-diagnosis-idiopathic-001', 'a4e0ba58-1b2c-576f-8e95-e698b74954f5', 'After negative imaging and laboratory evaluation, the pancreatitis was classified as idiopathic.', 'idiopathic', 'Scans and blood tests did not find a cause, so the pancreatitis was labeled as having no identified origin.', '影像和实验室评估均为阴性后，胰腺炎被归为特发性。', array['idiopathic disease', 'labeled idiopathic', 'adult-onset idiopathic']::text[], 'case_report', 'original_example', null, null, null, null),
  ('1ecc376b-26cd-56b7-9bd9-7ce52617519b', 'medical_english:diagnosis:iatrogenic:adjective:med-diagnosis-iatrogenic-001', '4d3b6ec4-b93e-5a4c-be93-8e6a45f5c5ef', 'The pneumothorax was iatrogenic after central venous catheter placement.', 'iatrogenic', 'The collapsed lung appeared after a central line was placed, not from the illness that brought the patient in.', '气胸发生在中心静脉置管之后，属医源性。', array['iatrogenic injury', 'iatrogenic complication', 'iatrogenic cause']::text[], 'case_report', 'original_example', null, null, null, null),
  ('81c3b738-742f-5016-949f-68a0f020ba72', 'medical_english:laboratory:thrombocytopenia:noun:med-laboratory-thrombocytopenia-001', '30dd3e35-65f8-5d9c-8398-d524e816cb95', 'The complete blood count showed isolated thrombocytopenia with a platelet count of 42 × 10^9/L.', 'thrombocytopenia', 'The blood count found a low platelet number and no other cell-line abnormality.', '血常规显示孤立性血小板减少，血小板计数为 42 × 10^9/L。', array['isolated thrombocytopenia', 'severe thrombocytopenia', 'heparin-induced thrombocytopenia']::text[], 'laboratory_report', 'original_example', null, null, null, null),
  ('44ffa888-0b53-5410-a785-6e800b7fd3a4', 'medical_english:laboratory:transaminitis:noun:med-laboratory-transaminitis-001', '608c8110-6aa9-511f-b646-b88b4b849549', 'Mild transaminitis was noted, with alanine aminotransferase twice the upper reference limit.', 'transaminitis', 'The liver enzyme alanine aminotransferase was about twice the usual upper limit, and the note used informal shorthand for that rise.', '记录到轻度转氨酶升高，丙氨酸氨基转移酶为参考上限的两倍。', array['mild transaminitis', 'isolated transaminitis', 'resolve the transaminitis']::text[], 'laboratory_report', 'original_example', null, null, null, null),
  ('7b87cfec-90d7-5ee1-b8bf-b45299e681a9', 'medical_english:imaging:effusion:noun:med-imaging-effusion-001', 'b6a38dc9-5da8-55b5-a601-2aab852b4370', 'The chest radiograph demonstrated a moderate right pleural effusion without pneumothorax.', 'effusion', 'The chest X-ray showed a moderate fluid collection around the right lung and no air leak.', '胸部 X 线片显示右侧中等量胸腔积液，无气胸。', array['pleural effusion', 'pericardial effusion', 'joint effusion']::text[], 'imaging_report', 'original_example', null, null, null, null),
  ('d7aedf81-f640-5c12-9c50-11758b6f0751', 'medical_english:imaging:infiltrate:noun:med-imaging-infiltrate-001', 'a18702ff-8bd9-5010-a03f-f95fbd407965', 'A new left-lower-lobe infiltrate was seen compared with the radiograph from two days earlier.', 'infiltrate', 'The new film showed a fuzzy dense patch in the lower left lung that had not been there two days before.', '与两天前的胸片相比，可见左下叶新出现浸润影。', array['pulmonary infiltrate', 'new infiltrate', 'patchy infiltrate']::text[], 'imaging_report', 'original_example', null, null, null, null),
  ('275143b6-79e3-515d-8b11-a056f3241d52', 'medical_english:treatment:empiric:adjective:med-treatment-empiric-001', '3656df7d-4338-56cc-8d05-0b3fc8dff5cc', 'Empiric vancomycin was started after blood cultures were drawn but before organism identification.', 'Empiric', 'Vancomycin was given based on the usual serious bacteria in this setting, after cultures were taken and before the organism was named.', '在抽血培养之后、病原体鉴定之前，开始经验性使用万古霉素。', array['empiric antibiotics', 'empiric therapy', 'empiric coverage']::text[], 'clinical_guideline', 'original_example', null, null, null, null),
  ('c053d257-eea5-58f0-b872-3020a06f9547', 'medical_english:treatment:prophylaxis:noun:med-treatment-prophylaxis-001', '2f78a5f1-0b6a-5b8c-9fd7-119795c6c8d7', 'Low-molecular-weight heparin was given for venous thromboembolism prophylaxis after hip replacement.', 'prophylaxis', 'A blood thinner was used to prevent clots after hip replacement, not to treat a clot that had already formed.', '髋关节置换后给予低分子肝素以预防静脉血栓栓塞。', array['thromboprophylaxis', 'antibiotic prophylaxis', 'primary prophylaxis']::text[], 'clinical_guideline', 'original_example', null, null, null, null),
  ('33226cc4-5a06-5244-b2ca-dc0652295667', 'medical_english:treatment:adjuvant:adjective:med-treatment-adjuvant-001', '52fef1fa-7fc8-5667-bcbd-69aa623442e8', 'Adjuvant chemotherapy was offered after complete resection of the node-positive tumor.', 'Adjuvant', 'Chemotherapy was proposed after the tumor and involved nodes had already been fully removed, to reduce the chance of return.', '在完整切除淋巴结阳性肿瘤后，建议给予辅助化疗。', array['adjuvant chemotherapy', 'adjuvant radiotherapy', 'adjuvant therapy']::text[], 'clinical_guideline', 'original_example', null, null, null, null),
  ('1dffb0e6-642b-5773-9a8b-621e5861a91f', 'medical_english:pharmacology:half-life:noun:med-pharmacology-half-life-001', 'b91c854c-3d81-5891-bed0-54b952cf0244', 'Because the drug has a 36-hour half-life, once-daily dosing is usually sufficient.', 'half-life', 'The amount of drug in the body falls by about half in a day and a half, so one dose a day is usually enough.', '该药半衰期为 36 小时，因此通常每日一次给药即可。', array['elimination half-life', 'prolonged half-life', 'plasma half-life']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('b70efa79-e206-57ef-8020-5ded72f413c1', 'medical_english:pharmacology:agonist:noun:med-pharmacology-agonist-001', 'b60ab1b2-ed67-58d8-af81-4a482b4d5364', 'A long-acting beta-2 receptor agonist relaxes airway smooth muscle.', 'agonist', 'The inhaled medicine turns on beta-2 receptors and thereby loosens the muscles around the airways.', '长效 β2 受体激动剂使气道平滑肌舒张。', array['receptor agonist', 'full agonist', 'beta-2 agonist']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('7de14bd4-e512-5d32-9f9c-e3a6311e5c85', 'medical_english:surgery_procedures:resection:noun:med-surgery-resection-001', 'cc430fba-84ac-58d0-b6a8-efd08164b3ec', 'Segmental small-bowel resection was performed, and bowel continuity was restored.', 'resection', 'A portion of small intestine was removed, and the remaining ends were joined again.', '施行了小肠节段切除，并恢复了肠道连续性。', array['surgical resection', 'complete resection', 'segmental resection']::text[], 'operative_note', 'original_example', null, null, null, null),
  ('d0e638b0-bd8d-50ee-9b3c-3d4268d475f3', 'medical_english:surgery_procedures:ligation:noun:med-surgery-ligation-001', '38c7a8cd-e47b-5754-8f7e-082656255219', 'The cystic artery was controlled with ligation before the gallbladder was taken down.', 'ligation', 'The artery to the gallbladder was tied off before the organ was separated from the liver.', '在游离胆囊之前，先结扎控制胆囊动脉。', array['vessel ligation', 'suture ligation', 'ligation and division']::text[], 'operative_note', 'original_example', null, null, null, null),
  ('11d1d92c-6a29-5c94-917e-f0002219fffa', 'medical_english:clinical_expressions:present-with:phrasal-verb:med-clinical-present-with-001', '1c993255-236c-591e-b7b8-77dc26033747', 'She presented with three days of fever and a productive cough.', 'presented with', 'When she sought care, she had already had fever and a cough that brought up sputum for three days.', '她因发热三天伴咳痰就诊。', array['present with fever', 'present with chest pain', 'initially presented with']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('a25b7ee1-4fa6-507b-b823-058f948ab997', 'medical_english:clinical_expressions:hemodynamically-stable:adjective:med-clinical-hemodynamically-stable-001', 'e2aae7e9-77a0-57ab-a146-7fb6a1d00d93', 'The patient remained hemodynamically stable after two liters of crystalloid.', 'hemodynamically stable', 'After two liters of intravenous fluid, blood pressure and organ perfusion were still adequate.', '输入两升晶体液后，患者仍保持血流动力学稳定。', array['remain hemodynamically stable', 'hemodynamically stable on arrival', 'no longer hemodynamically stable']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('cbc9ed88-fb26-5c95-9f50-fd3131039c92', 'medical_english:clinical_expressions:status-post:phrase:med-clinical-status-post-001', 'be3ae221-3f50-5216-867f-748128f4e561', 'The patient is status post laparoscopic cholecystectomy on hospital day two.', 'status post', 'By the second hospital day, the gallbladder had already been removed through small incisions.', '患者为住院第 2 天腹腔镜胆囊切除术后状态。', array['status post resection', 'status post fall', 'now status post']::text[], 'medical_record', 'original_example', null, null, null, null)
